#!/usr/bin/env bash
# reproduce.sh [run_id] — one command, end to end (run bootstrap.sh first):
#   (a) baseline check: on the base commit every hidden FAIL_TO_PASS test must fail with its DECLARED failure
#       (task/manifest.json → baseline_expected_failures) and every PASS_TO_PASS test must pass
#   (b) one autonomous agent run (run_agent.sh), with at most one injected fault (LC0_FAULT)
#   (c) independent evaluation of the agent's final SHA, twice (evaluate.sh: tests + diff policy), must be identical
#   → $LC0_WORK/runs/<run_id>/report.json + report.md   (generated by lib/report.py)
#
# LC0_REPORT_ONLY=1 ./reproduce.sh <run_id>
#   re-derives the report for an EXISTING run: reuses the saved agent result + trajectory (no agent run, no LLM calls),
#   re-runs the deterministic offline steps (baseline + 2 evaluations); the previous report is kept as report.prev.json.
#
# Three verdicts per run (see README "Verdicts"):
#   delivery_verdict  PASS | FAIL | ERROR | ESCALATE | INVALID_BASELINE   — product delivered and verified (unchanged meaning)
#   recovery.level    N/A | NONE | OBSERVED | WORKAROUND | ROOT_CAUSE_RESOLVED | CONTROLLED_STOP
#   lc0_verdict       requires BOTH delivery and acceptable recovery when a fault was injected
# Exit code = lc0_verdict: 0 PASS | 1 FAIL | 3 ERROR | 4 ESCALATE | 5 CONTROLLED_STOP | 6 INVALID_BASELINE
set -Eeuo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"; export ROOT
source "$ROOT/lib/common.sh"
RID=${1:-run-$(date +%Y%m%d-%H%M%S)}
[[ "$RID" =~ ^[A-Za-z0-9._-]+$ ]] || { echo "usage: $0 [run_id]" >&2; exit 2; }
RD="$LC0_WORK/runs/$RID"; EV="$LC0_WORK/evals/$RID"; mkdir -p "$EV"
[[ -f "$LC0_WORK/environment.json" ]] || die 3 "environment not bootstrapped: run ./bootstrap.sh first"
T0=$(date +%s)
BASE=$(git -C "$LC0_REPO" rev-parse main)

log "(a) baseline check on base $BASE"
BRC=0; "$ROOT/evaluate.sh" "$BASE" "$EV/baseline.json" || BRC=$?
if [[ "${LC0_REPORT_ONLY:-0}" == 1 ]]; then
  [[ -f "$RD/agent_result.json" ]] || die 3 "no saved agent result for $RID"
  [[ -f "$RD/report.json" ]] && cp "$RD/report.json" "$RD/report.prev.json"
  log "(b) REPORT_ONLY: reusing saved agent run (no LLM calls)"
  ARC=$(python3 -c "import json;print(json.load(open('$RD/agent_result.json'))['agent_exit_code'])")
  DUR=$(python3 -c "import json;print(json.load(open('$RD/report.prev.json'))['total_seconds'])" 2>/dev/null || echo 0)
else
  log "(b) agent run $RID (fault=$LC0_FAULT)"
  ARC=0; "$ROOT/run_agent.sh" "$RID" || ARC=$?
fi
FINAL=$(python3 -c "import json;print(json.load(open('$RD/agent_result.json')).get('final_sha') or '')" 2>/dev/null || true)
E1=0; E2=0; rm -f "$EV/eval_1.json" "$EV/eval_2.json"
if [[ -n "$FINAL" ]]; then
  log "(c) evaluating final SHA $FINAL twice"
  export LC0_EVAL_TRAJ="$RD/trajectory.json"
  "$ROOT/evaluate.sh" "$FINAL" "$EV/eval_1.json" || E1=$?
  "$ROOT/evaluate.sh" "$FINAL" "$EV/eval_2.json" || E2=$?
else
  log "(c) skipped: agent produced no final SHA"
fi
DUR=${DUR:-$(( $(date +%s) - T0 ))}
RC=0; python3 "$ROOT/lib/report.py" "$ROOT" "$RD" "$EV" "$BRC" "$ARC" "$E1" "$E2" "$DUR" || RC=$?
V=$(python3 -c "import json;d=json.load(open('$RD/report.json'));print(d['lc0_verdict'],'(delivery',d['delivery_verdict']+', recovery',d['recovery']['level']+')')" 2>/dev/null || echo "report failed")
log "LC0 VERDICT: $V — report: $RD/report.md"
exit $RC
